function minCoins(coins, amount) {
  const memo = new Map();
  function solve(rem) {
    if (rem === 0) return 0;
    if (rem < 0) return Infinity;
    if (memo.has(rem)) return memo.get(rem);
    let best = Infinity;
    for (const c of coins) {
      best = Math.min(best, solve(rem - c) + 1);
    }
    memo.set(rem, best);
    return best;
  }
  const result = solve(amount);
  return result === Infinity ? -1 : result;
}
